import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CSVPrinter_printRecords_TriageGen2Test {

    @Test
    public void testPrintRecords_EmptyResultSet() throws IOException, SQLException {
        StringWriter out = new StringWriter();
        CSVPrinter printer = new CSVPrinter(out, CSVFormat.DEFAULT);
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(2);
        when(resultSet.next()).thenReturn(false);

        printer.printRecords(resultSet);
        printer.close();

        assertEquals("", out.toString());
    }








}

package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CSVPrinter_printRecords_TriageGen2Test {



    @Test
    public void testPrintRecords_WithData() throws IOException, SQLException {
        StringWriter out = new StringWriter();
        CSVPrinter printer = new CSVPrinter(out, CSVFormat.DEFAULT);
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(2);

        // Row 1
        when(resultSet.next()).thenReturn(true, true, false);
        when(resultSet.getString(1)).thenReturn("A", "B");
        when(resultSet.getString(2)).thenReturn("1", "2");

        printer.printRecords(resultSet);
        printer.close();

        // CSVFormat.DEFAULT uses comma as delimiter and CRLF or LF depending on platform.
        // We normalize the newline for comparison.
        String result = out.toString().replace("\r\n", "\n").replace("\r", "\n");
        String expected = "A,1\nB,2\n";
        assertEquals(expected, result);
    }






}

